void *riven_stream_handle(FILE *stream) {
    FILE **handle = (FILE **)riven_alloc(sizeof(FILE *));
    *handle = stream;
    return handle;
}

FILE *riven_stream_from_handle(void *handle, FILE *fallback) {
    return handle ? *(FILE **)handle : fallback;
}

void *riven_stream_read_line(FILE *stream) {
    size_t cap = 128;
    size_t len = 0;
    char *buf = (char *)malloc(cap);
    int ch;

    if (!buf) {
        riven_panic("out of memory");
    }

    while ((ch = fgetc(stream)) != EOF) {
        if (len + 1 >= cap) {
            size_t next_cap = cap * 2;
            char *next = (char *)realloc(buf, next_cap);
            if (!next) {
                free(buf);
                riven_panic("out of memory");
            }
            buf = next;
            cap = next_cap;
        }
        buf[len++] = (char)ch;
        if (ch == '\n') {
            break;
        }
    }

    if (ferror(stream)) {
        int saved_errno = errno;
        free(buf);
        clearerr(stream);
        return riven_io_error_from_errno(saved_errno);
    }

    if (len == 0 && ch == EOF) {
        free(buf);
        return riven_result_err_value(
            (int64_t)riven_io_error_unit(RIVEN_IO_ERROR_UNEXPECTED_EOF));
    }

    buf[len] = '\0';
    return riven_result_ok_value((int64_t)buf);
}

int riven_saved_argc = 0;
char **riven_saved_argv = NULL;

void riven_free_saved_argv(void) {
    if (!riven_saved_argv) {
        return;
    }

    for (int i = 0; i < riven_saved_argc; i++) {
        free(riven_saved_argv[i]);
    }
    free(riven_saved_argv);
    riven_saved_argv = NULL;
    riven_saved_argc = 0;
}

